+import { Recur } from './recur.ts';
+
+/**
+ * Resolves recur placeholders in a schema.
+ *
+ * @param value The schema value.
+ * @param recursive The recursive schema.
+ * @param cache The clone cache.
+ *
+ * @returns The resolved schema value.
+ *
+ * @internal
+ */
+export function _resolveRecur<TValue>(
+  value: TValue,
+  recursive: unknown,
+  cache = new WeakMap<object, object>()
+): TValue {
+  if (value === Recur) {
+    return recursive as TValue;
+  }
+  if (!value || typeof value !== 'object') {
+    return value;
+  }
+  if (value instanceof Map || value instanceof Set || value instanceof Date) {
+    return value;
+  }
+
+  const cached = cache.get(value);
+  if (cached) {
+    return cached as TValue;
+  }
+
+  const clone: object = Array.isArray(value)
+    ? []
+    : Object.create(Object.getPrototypeOf(value));
+  cache.set(value, clone);
+  for (const [key, descriptor] of Object.entries(
+    Object.getOwnPropertyDescriptors(value)
+  )) {
+    if ('value' in descriptor) {
+      descriptor.value = _resolveRecur(descriptor.value, recursive, cache);
+    }
+    Object.defineProperty(clone, key, descriptor);
+  }
+  return clone as TValue;
+}
