// @__NO_SIDE_EFFECTS__
export function pipe<
  const TSchema extends BaseSchema<unknown, unknown, BaseIssue<unknown>>,
  const TItems extends readonly PipeItem<
    unknown,
    unknown,
    BaseIssue<unknown>
  >[],
>(
  ...pipe: [TSchema, ...TItems]
): SchemaWithPipe<readonly [TSchema, ...TItems]> {
  return {
    ...pipe[0],
    pipe,
    get '~standard'() {
      return _getStandardProps(this);
    },
    '~run'(dataset, config) {
      // Execute pipeline items in sequence
      for (const item of pipe) {
        // Exclude metadata items from execution
        if (item.kind !== 'metadata') {
          // Mark dataset as untyped and break pipe if there are issues and pipe
          // item is schema or transformation
          if (
            dataset.issues &&
            (item.kind === 'schema' || item.kind === 'transformation')
          ) {
            dataset.typed = false;
            break;
          }

          // Continue pipe execution if there is no reason to abort early
          if (
            !dataset.issues ||
            (!config.abortEarly && !config.abortPipeEarly)
          ) {
            // @ts-expect-error
            dataset = item['~run'](dataset, config);
          }
        }
      }

      // Return output dataset
      // @ts-expect-error
      return dataset as OutputDataset<unknown, BaseIssue<unknown>>;
    },
  };
}
import { Recur } from './recur.ts';

/**
 * Resolves recur placeholders in a schema.
 *
 * @param value The schema value.
 * @param recursive The recursive schema.
 * @param cache The clone cache.
 *
 * @returns The resolved schema value.
 *
 * @internal
 */
export function _resolveRecur<TValue>(
  value: TValue,
  recursive: unknown,
  cache: WeakMap<object, object> = new WeakMap<object, object>()
): TValue {
  if (value === Recur) {
    return recursive as TValue;
  }
  if (!value || typeof value !== 'object') {
    return value;
  }
  if (value instanceof Map || value instanceof Set || value instanceof Date) {
    return value;
  }

  const cached = cache.get(value);
  if (cached) {
    return cached as TValue;
  }

  const clone: object = Array.isArray(value)
    ? []
    : Object.create(Object.getPrototypeOf(value));
  cache.set(value, clone);
  for (const [key, descriptor] of Object.entries(
    Object.getOwnPropertyDescriptors(value)
  )) {
    if ('value' in descriptor) {
      descriptor.value = _resolveRecur(descriptor.value, recursive, cache);
    }
    Object.defineProperty(clone, key, descriptor);
  }
  return clone as TValue;
}
